<template>
  <section class="channels">
    <p>同一家货运公司可维护多个国家、路线和货物类型。每次调价发布新版本；发运批次保留所选报价，实际货运费用在“费用与结算”登记。</p>
    <div class="toolbar"><el-input v-model="search" placeholder="渠道编码 / 名称 / 起运地" aria-label="搜索运输渠道" @keyup.enter="searchChannels"/><el-button @click="searchChannels">查询</el-button><el-button v-if="canWrite" type="primary" @click="openChannel()">新增运输渠道</el-button></div>
    <el-alert v-if="error" type="error" :title="error" :closable="false"/>
    <el-table :data="channels" border v-loading="loading"><el-table-column label="运输渠道" min-width="170"><template #default="{row}"><strong>{{row.name}}</strong><small>{{row.code}} · {{row.is_active?'启用':'停用'}}</small></template></el-table-column><el-table-column label="线路与货物" min-width="190"><template #default="{row}">{{row.origin}} → {{row.country_name}}<small>{{modeLabel(row.transport_mode)}} · {{row.cargo_type}}</small></template></el-table-column><el-table-column label="当前有效报价" min-width="220"><template #default="{row}"><template v-if="row.current_quote">{{quoteLabel(row.current_quote)}}<small>v{{row.current_quote.sequence}} · {{row.current_quote.effective_from}} 起 · {{row.current_quote.prices_include_tax?'含税':'未税'}} / 税点 {{row.current_quote.tax_percent}}%</small></template><span v-else>未发布或报价已过期</span></template></el-table-column><el-table-column label="操作" min-width="245"><template #default="{row}"><el-button link @click="openChannel(row)">{{canWrite?'编辑渠道':'查看渠道'}}</el-button><el-button link @click="showHistory(row)">报价历史</el-button><el-button v-if="canWrite" link type="primary" :disabled="!row.is_active || !company.is_active" @click="openQuote(row)">发布报价</el-button></template></el-table-column></el-table>
    <el-pagination layout="total,prev,pager,next" :total="total" :page-size="20" :current-page="page" @current-change="value=>{page=value;load()}"/>
    <el-dialog class="sc2-scroll-dialog" top="4vh" v-model="channelOpen" :title="`${editing?'编辑':'新增'}运输渠道`" width="min(680px,96vw)" :close-on-click-modal="!busy" :show-close="!busy" :close-on-press-escape="!busy" append-to-body>
      <p>货运公司：{{company.name}}。已发布报价的渠道，其国家、起运地、货物类型和运输方式固定；新线路请另建渠道。</p>
      <el-form label-position="top" class="form-grid" :disabled="!canWrite || busy"><el-form-item label="渠道编码"><el-input v-model="channelForm.code" aria-label="渠道编码" :disabled="hasPublished"/></el-form-item><el-form-item label="渠道名称"><el-input v-model="channelForm.name" aria-label="渠道名称"/></el-form-item><el-form-item label="目的国家"><el-select v-model="channelForm.country_id" aria-label="渠道目的国家" :disabled="hasPublished"><el-option v-for="country in countries" :key="country.id" :value="country.id" :label="`${country.name}（${country.country_code || country.code}）`"/></el-select></el-form-item><el-form-item label="起运地 / 出口路线"><el-input v-model="channelForm.origin" aria-label="渠道起运地" :disabled="hasPublished"/></el-form-item><el-form-item label="货物类型"><el-input v-model="channelForm.cargo_type" aria-label="渠道货物类型" placeholder="例如 普货、带电" :disabled="hasPublished"/></el-form-item><el-form-item label="运输方式"><el-select v-model="channelForm.transport_mode" aria-label="渠道运输方式" :disabled="hasPublished"><el-option v-for="(label,value) in modes" :key="value" :value="value" :label="label"/></el-select></el-form-item><el-form-item label="启用"><el-switch v-model="channelForm.is_active" aria-label="启用运输渠道"/></el-form-item><el-form-item label="备注" class="full"><el-input v-model="channelForm.notes" aria-label="渠道备注" type="textarea"/></el-form-item></el-form>
      <el-alert v-if="formError" :title="formError" type="error" :closable="false"/><template #footer><el-button :disabled="busy" @click="channelOpen=false">关闭</el-button><el-button v-if="canWrite" type="primary" :loading="busy" @click="saveChannel">保存渠道</el-button></template>
    </el-dialog>
    <el-dialog class="sc2-scroll-dialog" top="4vh" v-model="quoteOpen" :title="`${quoting?.name || ''} · 发布新报价`" width="min(680px,96vw)" :close-on-click-modal="!busy" :close-on-press-escape="!busy" :show-close="!busy" append-to-body>
      <p>发布后保留历史版本。新版本自生效日期起替代先前报价；填写截止日期后，过期不会恢复旧报价。</p>
      <el-form label-position="top" class="form-grid" :disabled="!canWrite || busy"><el-form-item label="生效日期"><el-date-picker v-model="quoteForm.effective_from" value-format="YYYY-MM-DD" aria-label="货运报价生效日期"/></el-form-item><el-form-item label="截止日期（可留空）"><el-date-picker v-model="quoteForm.effective_to" value-format="YYYY-MM-DD" aria-label="货运报价截止日期"/></el-form-item><el-form-item label="计费方式"><el-select v-model="quoteForm.billing_basis" aria-label="货运报价计费方式"><el-option value="cbm" label="按方"/><el-option value="container" label="按柜"/></el-select></el-form-item><el-form-item v-if="quoteForm.billing_basis==='cbm'" label="每方价格"><el-input v-model="quoteForm.fee_per_cbm" inputmode="decimal" aria-label="渠道每方价格"/></el-form-item><template v-else><el-form-item label="柜型"><el-input v-model="quoteForm.container_type" placeholder="例如 40HQ" aria-label="报价柜型"/></el-form-item><el-form-item label="整柜价格"><el-input v-model="quoteForm.container_fee" inputmode="decimal" aria-label="渠道整柜价格"/></el-form-item></template><el-form-item label="税费点数 (%)"><el-input v-model="quoteForm.tax_percent" inputmode="decimal" aria-label="报价税费点数"/></el-form-item><el-form-item label="报价已含税"><el-switch v-model="quoteForm.prices_include_tax" aria-label="报价已含税"/></el-form-item><el-form-item label="发布 / 调价原因" class="full"><el-input v-model="quoteForm.reason" aria-label="报价发布原因" maxlength="500"/></el-form-item><el-form-item label="备注" class="full"><el-input v-model="quoteForm.notes" aria-label="货运报价备注" type="textarea"/></el-form-item></el-form>
      <el-alert v-if="formError" :title="formError" type="error" :closable="false"/><template #footer><el-button :disabled="busy" @click="quoteOpen=false">关闭</el-button><el-button type="primary" :loading="busy" :disabled="!canWrite" @click="publishQuote">发布报价版本</el-button></template>
    </el-dialog>
    <el-dialog class="sc2-scroll-dialog" top="4vh" v-model="historyOpen" :title="`${historyChannel?.name || ''} · 报价历史`" width="min(900px,96vw)" append-to-body><el-alert v-if="historyError" :title="historyError" type="error" :closable="false"/><el-table :data="history" border><el-table-column prop="sequence" label="版本" width="65"/><el-table-column label="报价" min-width="180"><template #default="{row}">{{quoteLabel(row)}}<small>{{row.prices_include_tax?'含税':'未税'}} · {{row.tax_percent}}%</small></template></el-table-column><el-table-column prop="effective_from" label="生效日期"/><el-table-column prop="effective_to" label="截止日期"/><el-table-column prop="reason" label="发布原因" min-width="180"/></el-table><el-pagination layout="total,prev,pager,next" :total="historyTotal" :page-size="20" :current-page="historyPage" @current-change="value=>{historyPage=value;loadHistory()}"/></el-dialog>
  </section>
</template>
<script setup>
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue';
import '../../styles/supplyCollaboration.css';
import { ElMessage } from 'element-plus';
import { useAuthStore } from '../../stores/auth';
import { createIdempotencyKey, fetchSupplyOptions } from '../../api/supplyChainV2';
import * as api from '../../api/supplyFreightChannelsV2';
const props=defineProps({company:{type:Object,required:true}});
const auth=useAuthStore(),canWrite=computed(()=>!auth.authorizationStale&&auth.hasPermission('supply.v2.manage'));
const channels=ref([]),countries=ref([]),loading=ref(false),busy=ref(false),error=ref(''),formError=ref(''),search=ref(''),page=ref(1),total=ref(0),businessDate=ref('');
const channelOpen=ref(false),quoteOpen=ref(false),editing=ref(null),quoting=ref(null),hasPublished=ref(false);
const channelForm=reactive({code:'',name:'',country_id:null,origin:'',cargo_type:'',transport_mode:'sea',notes:'',is_active:true});
const quoteForm=reactive({effective_from:'',effective_to:null,billing_basis:'cbm',fee_per_cbm:'',container_fee:'',container_type:'',tax_percent:'0',prices_include_tax:false,notes:'',reason:''});
const historyOpen=ref(false),historyChannel=ref(null),history=ref([]),historyError=ref(''),historyPage=ref(1),historyTotal=ref(0);
const modes={sea:'海运',air:'空运',road:'陆运',rail:'铁路',other:'其他'};
const modeLabel=value=>modes[value]||value;
const quoteLabel=quote=>quote.billing_basis==='container'?`${quote.container_type} · ${quote.container_fee} / 柜`:`${quote.fee_per_cbm} / 方`;
const unwrap=r=>{if(!r?.success)throw new Error(r?.message||'请求失败');return r.data;};
let loadToken=0,historyToken=0;const pending=new Map();
async function mutate(slot,body,execute){const fingerprint=JSON.stringify(body);let entry=pending.get(slot);if(!entry||entry.fingerprint!==fingerprint){entry={fingerprint,key:createIdempotencyKey()};pending.set(slot,entry);}const result=await execute(entry.key);unwrap(result);pending.delete(slot);return result;}
async function load(){const token=++loadToken;loading.value=true;error.value='';try{const result=await api.fetchFreightChannels({company_id:props.company.id,search:search.value,limit:20,offset:(page.value-1)*20});if(token!==loadToken)return;channels.value=unwrap(result)||[];total.value=result.count||0;businessDate.value=result.business_date||'';}catch(e){if(token===loadToken)error.value=e.message;}finally{if(token===loadToken)loading.value=false;}}
function searchChannels(){page.value=1;load();}
async function openChannel(row){editing.value=row||null;Object.assign(channelForm,row||{code:'',name:'',country_id:null,origin:'',cargo_type:'',transport_mode:'sea',notes:'',is_active:true});hasPublished.value=false;formError.value='';channelOpen.value=true;if(row){try{const result=await api.fetchFreightQuotes(row.id,{limit:1});if(editing.value?.id===row.id&&channelOpen.value)hasPublished.value=Number(result.count||0)>0;}catch(e){formError.value=e.message;}}}
async function saveChannel(){if(!canWrite.value||busy.value)return;const body={company_id:props.company.id,...Object.fromEntries(Object.keys(channelForm).filter(key=>['code','name','country_id','origin','cargo_type','transport_mode','notes','is_active'].includes(key)).map(key=>[key,channelForm[key]]))};if(editing.value)body.expected_version=editing.value.version;busy.value=true;formError.value='';try{await mutate(`channel-${editing.value?.id||'new'}`,body,key=>editing.value?api.updateFreightChannel(editing.value.id,body,key):api.createFreightChannel(body,key));channelOpen.value=false;await load();ElMessage.success('运输渠道已保存。');}catch(e){formError.value=e.message;}finally{busy.value=false;}}
function openQuote(row){quoting.value={...row};const quote=row.current_quote||{};Object.assign(quoteForm,{effective_from:businessDate.value||new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'}),effective_to:null,billing_basis:quote.billing_basis||'cbm',fee_per_cbm:quote.fee_per_cbm??'',container_fee:quote.container_fee??'',container_type:quote.container_type||'',tax_percent:quote.tax_percent??'0',prices_include_tax:quote.prices_include_tax||false,notes:'',reason:''});formError.value='';quoteOpen.value=true;}
async function publishQuote(){if(!canWrite.value||busy.value||!quoting.value)return;if(!quoteForm.reason.trim()){formError.value='请填写发布或调价原因。';return;}const number=value=>value==null||String(value).trim()===''?null:String(value).trim();const body={...quoteForm,fee_per_cbm:quoteForm.billing_basis==='cbm'?number(quoteForm.fee_per_cbm):null,container_fee:quoteForm.billing_basis==='container'?number(quoteForm.container_fee):null,effective_to:quoteForm.effective_to||null,expected_channel_version:quoting.value.version};busy.value=true;formError.value='';try{await mutate(`quote-${quoting.value.id}`,body,key=>api.publishFreightQuote(quoting.value.id,body,key));quoteOpen.value=false;await load();ElMessage.success('新报价已发布，历史批次报价保持不变。');}catch(e){formError.value=e.message;}finally{busy.value=false;}}
async function showHistory(row){historyChannel.value=row;historyPage.value=1;historyOpen.value=true;await loadHistory();}
async function loadHistory(){const token=++historyToken;historyError.value='';history.value=[];try{const result=await api.fetchFreightQuotes(historyChannel.value.id,{limit:20,offset:(historyPage.value-1)*20});if(token!==historyToken)return;history.value=unwrap(result)||[];historyTotal.value=result.count||0;}catch(e){if(token===historyToken)historyError.value=e.message;}}
onMounted(async()=>{load();try{countries.value=unwrap(await fetchSupplyOptions({kind:'countries',limit:100}))||[];}catch(e){error.value=e.message;}});
watch(()=>props.company.id,()=>{page.value=1;channelOpen.value=false;quoteOpen.value=false;historyOpen.value=false;load();});
onUnmounted(()=>{loadToken++;historyToken++;});
defineExpose({channels,canWrite,channelForm,quoteForm,hasPublished,openChannel,openQuote,saveChannel,publishQuote,load});
</script>
<style scoped>
.channels>p{color:#64748b;font-size:13px;line-height:1.8}.toolbar{display:flex;gap:10px;flex-wrap:wrap;margin:16px 0}.toolbar .el-input{width:min(320px,100%)}small{display:block;font-size:12px;line-height:1.7;color:#64748b;margin-top:5px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}.full{grid-column:1/-1}.form-grid :deep(.el-select),.form-grid :deep(.el-date-editor){width:100%}@media(max-width:620px){.form-grid{grid-template-columns:1fr}.full{grid-column:1}}
</style>
